UPDATE `quest_offer_reward_locale` SET `RewardText`='Хорошая работа, $N! Я уж постараюсь, чтобы мои сородичи узнали о твоих делах.$B$BНе забывай приносить мне все перья, что добудешь. Я возьму все, сколько принесешь.' WHERE `ID`=8466 AND `locale`='ruRU' AND MD5(`RewardText`)='c1ef50778dc68dc48e004520642e2125';
