UPDATE `quest_offer_reward_locale` SET `RewardText`='Не забывай, $N! мозг цел – есть шансы выжить. Носи этот шлем, не снимая!' WHERE `ID`=9037 AND `locale`='ruRU' AND MD5(`RewardText`)='871b926144c6246f85cfce5ecac2a39e';
