UPDATE `quest_offer_reward_locale` SET `RewardText`='Спасибо, $N. Твоя $Gхрабрый:хитрая; и $Gмудрый:мудрая;. $B$BРасскажи мне, каково было действие яда?' WHERE `ID`=9051 AND `locale`='ruRU' AND MD5(`RewardText`)='44caba52178b2a52af1f7550d3812094';
