UPDATE `quest_offer_reward_locale` SET `RewardText`='А ты $Gбыстр:быстра;, $N! $GБыстр:быстра;, как лисица...' WHERE `ID`=9126 AND `locale`='ruRU' AND MD5(`RewardText`)='d5225fd2dfb5bb52a87d526d02c36bea';
