UPDATE `quest_request_items_locale` SET `CompletionText`='Ты $Gпринес:принесла; грибы-малиновики, которые нужны мне для работы? Нет грибов – нет награды!' WHERE `ID`=17 AND `locale`='ruRU' AND MD5(`CompletionText`)='081947e31722fb6440d20f610495656b';
