UPDATE `quest_request_items_locale` SET `CompletionText`='Приветствую тебя, $N. Какие новости? Что удалось обнаружить в Яшмовой шахте?' WHERE `ID`=76 AND `locale`='ruRU' AND MD5(`CompletionText`)='a8f4095a7b0fa0adf1e5b7da172247c7';
