UPDATE `quest_request_items_locale` SET `CompletionText`='Рад тебя видеть, $N. Бизнес процветает, Молоты звенят по наковальням, меха раздувают огонь, а моя жена готовит мне пирог на десерт... Жизнь прекрасна, не так ли?' WHERE `ID`=1467 AND `locale`='ruRU' AND MD5(`CompletionText`)='edd352924c93992946cade3853ca2fd9';
UPDATE `quest_request_items_locale` SET `CompletionText`='Наконец-то вы вернулись, $N! Давненько мы не виделись, я было подумал, что вы забыли о моем поручении...$B$BВы нашли этого хитроумного всадника? Он что-нибудь сказал?' WHERE `ID`=1469 AND `locale`='ruRU' AND MD5(`CompletionText`)='2f8c20426e7781dbfe6270116e37ee3f';
