UPDATE `quest_request_items_locale` SET `CompletionText`='Мы отражаем их нападения, а они все лезут и лезут! Их явно что-то гонит... Или, может быть, кто-то? А, $N, ты уже $Gвернулся:вернулась;? Ну что, гривы при тебе?' WHERE `ID`=2862 AND `locale`='ruRU' AND MD5(`CompletionText`)='250a1a35bef1386cd96bbe0b4526b394';
