UPDATE `quest_request_items_locale` SET `CompletionText`='Приветствую, $Gмилый:милая; $C! За весь этот длинный день у меня не было ни одного удачного эксперимента. Надеюсь услышать от вас хорошие новости.' WHERE `ID`=2933 AND `locale`='ruRU' AND MD5(`CompletionText`)='21d9e20bbd347ff97e363b78f40136a0';
